import { CurrencyPipe, DatePipe } from '@angular/common';
import { Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ActivatedRoute } from '@angular/router';
import { EMPTY, catchError, map, switchMap } from 'rxjs';
import { BuchungenService } from '../shared/api/buchungen.service';
import { BuchungDetail } from '../shared/models/buchung-detail';
import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
import { spielstaettenOffset } from '../shared/utils/zeitzone';

type Ladezustand = 'laedt' | 'geladen' | 'fehler';

@Component({
  selector: 'app-buchungsdetail',
  imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
  templateUrl: './buchungsdetail.html',
  styleUrl: './buchungsdetail.scss',
})
export class Buchungsdetail {
  private readonly buchungenService = inject(BuchungenService);
  private readonly route = inject(ActivatedRoute);

  readonly ladezustand = signal<Ladezustand>('laedt');
  readonly buchung = signal<BuchungDetail | null>(null);

  protected readonly spielstaettenOffset = spielstaettenOffset;

  constructor() {
    this.route.paramMap
      .pipe(
        map((paramMap) => paramMap.get('referenz')!),
        switchMap((referenz) => {
          this.ladezustand.set('laedt');
          return this.buchungenService.buchungAbrufen(referenz).pipe(
            catchError(() => {
              this.ladezustand.set('fehler');
              return EMPTY;
            }),
          );
        }),
        takeUntilDestroyed(),
      )
      .subscribe((buchung) => {
        this.buchung.set(buchung);
        this.ladezustand.set('geladen');
      });
  }
}
=== buchungsdetail.html ===
@if (ladezustand() === 'laedt') {
  <p class="buchungsdetail__ladehinweis">Buchung wird geladen …</p>
} @else if (ladezustand() === 'fehler') {
  <p class="buchungsdetail__fehler" role="alert">Keine Buchung mit dieser Referenz gefunden.</p>
} @else if (buchung(); as b) {
  <main class="buchungsdetail">
    <h1 class="buchungsdetail__titel">{{ b.veranstaltungTitel }}</h1>
    <app-badge-status [status]="b.status" />
    <app-buchungsreferenz [referenz]="b.referenz" />
    <p class="buchungsdetail__zeitpunkt">
      {{
        b.veranstaltungZeitpunkt
          | date: 'EEEE, d. MMMM y, HH:mm' : spielstaettenOffset(b.veranstaltungZeitpunkt)
      }}
      Uhr · {{ b.spielstaetteName }}, {{ b.raumName }}
    </p>
    <ul class="buchungsdetail__positionen">
      @for (position of b.positionen; track position.sitzplatzCode) {
        <li class="buchungsdetail__position">
          <span class="buchungsdetail__code">{{ position.sitzplatzCode }}</span>
          <span class="buchungsdetail__kategorie">{{ position.preiskategorieName }}</span>
          <span class="buchungsdetail__einzelpreis">{{
            position.preisSnapshot | currency: 'EUR'
          }}</span>
        </li>
      }
    </ul>
    <p class="buchungsdetail__gesamtpreis">Gesamtpreis: {{ b.gesamtpreis | currency: 'EUR' }}</p>
  </main>
}
