import { Routes } from '@angular/router';
import { BuchungAbrufen } from './buchung-abrufen/buchung-abrufen';
import { Buchungsdetail } from './buchung-abrufen/buchungsdetail';
import { Buchung } from './buchung/buchung';
import { Programmuebersicht } from './programmuebersicht/programmuebersicht';
import { Veranstaltungsdetail } from './veranstaltungsdetail/veranstaltungsdetail';

export const routes: Routes = [
  { path: '', component: Programmuebersicht },
  { path: 'buchung-abrufen', component: BuchungAbrufen },
  { path: 'buchungen/:referenz', component: Buchungsdetail },
  { path: 'veranstaltungen/:id/buchung', component: Buchung },
  { path: 'veranstaltungen/:id', component: Veranstaltungsdetail },
];
---
import { Component, input, signal } from '@angular/core';

@Component({
  selector: 'app-buchungsreferenz',
  imports: [],
  templateUrl: './buchungsreferenz.html',
  styleUrl: './buchungsreferenz.scss',
})
export class Buchungsreferenz {
  readonly referenz = input.required<string>();

  protected readonly kopiert = signal(false);

  protected async kopieren(): Promise<void> {
    try {
      await navigator.clipboard.writeText(this.referenz());
      this.kopiert.set(true);
      setTimeout(() => this.kopiert.set(false), 2000);
    } catch {
      // Clipboard-API kann in unsicheren Kontexten/älteren Browsern fehlen — die Referenz
      // bleibt sichtbar und lässt sich manuell markieren, kein Fallback-Mechanismus nötig.
    }
  }
}

