  - [ ] `seed-a-frontend/src/app/buchung-abrufen/buchungsdetail.ts` erweitern:
    ```typescript
    import { CurrencyPipe, DatePipe } from '@angular/common';
    import { Component, DestroyRef, ElementRef, inject, signal, viewChild } from '@angular/core';
    import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
    import { ActivatedRoute } from '@angular/router';
    import { EMPTY, catchError, map, switchMap } from 'rxjs';
    import { BuchungenService } from '../shared/api/buchungen.service';
    import { BuchungDetail } from '../shared/models/buchung-detail';
    import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
    import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
    import { spielstaettenOffset } from '../shared/utils/zeitzone';

    type Ladezustand = 'laedt' | 'geladen' | 'fehler';

    @Component({
      selector: 'app-buchungsdetail',
      imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
      templateUrl: './buchungsdetail.html',
      styleUrl: './buchungsdetail.scss',
    })
    export class Buchungsdetail {
      private readonly buchungenService = inject(BuchungenService);
      private readonly route = inject(ActivatedRoute);
      private readonly destroyRef = inject(DestroyRef);

      readonly ladezustand = signal<Ladezustand>('laedt');
      readonly buchung = signal<BuchungDetail | null>(null);
      readonly stornierungLaeuft = signal(false);
      readonly stornierungErfolgreich = signal(false);
      readonly stornierungFehler = signal<string | null>(null);

      protected readonly spielstaettenOffset = spielstaettenOffset;
      private readonly stornierenDialog = viewChild.required<ElementRef<HTMLDialogElement>>('stornierenDialog');

      constructor() {
        // bestehender Lade-Konstruktor unveraendert (siehe aktuelle Datei)
      }

      protected dialogOeffnen(): void {
        this.stornierungFehler.set(null);
        this.stornierenDialog().nativeElement.showModal();
      }

      protected dialogAbbrechen(): void {
        this.stornierenDialog().nativeElement.close();
      }

      protected stornierenBestaetigen(): void {
        const aktuelleBuchung = this.buchung();
        if (!aktuelleBuchung || this.stornierungLaeuft()) return;

        this.stornierungLaeuft.set(true);
        this.buchungenService
          .buchungStornieren(aktuelleBuchung.referenz)
          .pipe(takeUntilDestroyed(this.destroyRef))
          .subscribe({
            next: (aktualisiert) => {
              this.stornierungLaeuft.set(false);
              this.buchung.set(aktualisiert);
              this.stornierungErfolgreich.set(true);
              this.stornierenDialog().nativeElement.close();
            },
            error: () => {
              this.stornierungLaeuft.set(false);
              this.stornierungFehler.set('Diese Buchung wurde bereits storniert.');
              this.stornierenDialog().nativeElement.close();
            },
          });
      }
    }
    ```
    **Warum natives `<dialog>` + `showModal()` statt einer selbstgebauten Modal-Komponente:** Das Projekt hat keine Angular-CDK-/Material-Abhängigkeit installiert (`package.json` geprüft — nur `@angular/core`, `@angular/common`, `@angular/forms`, `@angular/platform-browser`, `@angular/router`). Das native `<dialog>`-Element erfüllt AC #1 vollständig ohne Zusatzabhängigkeit: `showModal()` trappt den Fokus browserseitig automatisch (Tab zykliert nur innerhalb des Dialogs), und `Esc` löst standardmäßig das `cancel`-Event aus und schließt den Dialog ohne jede weitere Aktion — kein eigener `keydown`-Handler nötig, solange `cancel` nicht mit `preventDefault()` abgefangen wird. Dies ist die erste Verwendung von `<dialog>` im Projekt.
    **Warum `viewChild.required<ElementRef<HTMLDialogElement>>('stornierenDialog')` statt `@ViewChild`:** Das Projekt verwendet durchgängig die Signal-APIs (`input()`, `signal()`) statt Decorator-basiertem State (siehe `badge-status.ts`, `buchungsdetail.ts` selbst) — `viewChild` ist das Signal-Äquivalent zu `@ViewChild` und wird hier konsistent dazu eingesetzt. `.required(...)` ist zulässig, da das `#stornierenDialog`-Element (siehe Task 7) im selben `@else if`-Zweig wie der Rest der Detailansicht gerendert wird, also immer vorhanden ist, sobald diese Klasse aktiv genutzt wird.
    **Warum `takeUntilDestroyed(this.destroyRef)` explizit statt argumentlos:** 1:1 dieselbe Begründung wie in `buchung-abrufen.ts` (Story 3.1) — `stornierenBestaetigen()` wird durch einen späteren Klick-Handler aufgerufen, nicht im Constructor-Injection-Context, daher muss `DestroyRef` explizit injiziert und übergeben werden.

